    id: 'demo-2',
    creator_name: 'Elena Rostova',
    creator_avatar_url: null,
    message: 'The micro-interactions and audio feedback on Space UI are next-level. Absolute pure craft! ✨',
    patternIndex: 1,
    rotation: 4,
    created_at: new Date(Date.now() - 3600000 * 24 * 2).toISOString(),
  },
  {
    id: 'demo-3',
    creator_name: 'Marcus Vance',
    creator_avatar_url: null,
    message: 'Finally a UI kit that cares about OKLCH colors, fluid typography, and delightful physics.',
