  },
  {
    id: 'demo-4',
    creator_name: 'Sophie Lin',
    creator_avatar_url: null,
    message: 'Building our entire SaaS design tokens on top of this. The Base UI foundation is unmatched.',
    patternIndex: 3,
    rotation: 5,
    created_at: new Date(Date.now() - 3600000 * 12).toISOString(),
  },
  {
    id: 'demo-5',
    creator_name: 'Devon Miles',
    creator_avatar_url: null,
    message: 'The draggable infinite canvas feels as smooth as Figma. Incredible work team!',
    patternIndex: 4,
    rotation: -4,
    created_at: new Date(Date.now() - 3600000 * 8).toISOString(),
  },
  {
    id: 'demo-6',
    creator_name: 'Aria Chen',
    creator_avatar_url: null,
    message: 'Dropped shadcn for Space UI and haven’t looked back once. Keep shipping!',
    patternIndex: 5,
    rotation: 2,
    created_at: new Date(Date.now() - 3600000 * 4).toISOString(),
  },
  {
    id: 'demo-7',
    creator_name: 'Lucas Dupont',
    creator_avatar_url: null,
    message: 'Salutations de Paris! Space UI brings back the joy of crafting web interfaces.',
    patternIndex: 6,
    rotation: 6,
    created_at: new Date(Date.now() - 3600000 * 2).toISOString(),
  },
]

export interface CommunityWallProps {
  messages?: CommunityMessage[]
  onAddNote?: (note: {
    creator_name: string
    message: string
    pattern_index: number
    rotation: number
    creator_avatar_url?: string | null
  }) => Promise<boolean | void>
  className?: string
  height?: string | number
  user?: any
}

export function CommunityWall({
  messages: externalMessages,
  onAddNote,
  className,
  height,
  user,
}: CommunityWallProps) {
  const [messages, setMessages] = useState<CommunityMessage[]>(
    externalMessages && externalMessages.length > 0 ? externalMessages : DEFAULT_COMMUNITY_NOTES,
  )
  const [open, setOpen] = useState(false)

  useEffect(() => {
    if (externalMessages && externalMessages.length > 0) {
      setMessages(externalMessages)
    }
  }, [externalMessages])

  const handleAddNote = async (newNote: {
    creator_name: string
    message: string
    pattern_index: number
    rotation: number
    creator_avatar_url?: string | null
  }) => {
    if (onAddNote) {
      const success = await onAddNote(newNote)
      if (success === false) return false
    }

    const created: CommunityMessage = {
      id: 'local-' + Date.now(),
      creator_name: newNote.creator_name,
      message: newNote.message,
      patternIndex: newNote.pattern_index,
      pattern_index: newNote.pattern_index,
      rotation: newNote.rotation,
      creator_avatar_url: newNote.creator_avatar_url,
      created_at: new Date().toISOString(),
    }
    setMessages((prev) => [created, ...prev])
    return true
  }

  return (
    <div
      style={height ? { height: typeof height === 'number' ? `${height}px` : height } : undefined}
      className={cn('relative size-full', className)}
    >
      {/* Floating Leave Note Trigger Button */}
      <div className="absolute top-4 left-4 z-20">
        <Button
          type="button"
          variant="default"
          onClick={() => setOpen(true)}
          className="rounded-2xl flex items-center gap-3 px-5 py-3 shadow-md"
        >
          <div className="relative">
            <StatusBadge
              status={user ? 'online' : 'busy'}
              showIndicator
              animated
              size="sm"
              className="bg-inherit"
            />
          </div>
          <span className="text-sm font-medium">Leave a Note</span>
        </Button>
      </div>

      {/* Mobile: Grid layout */}
      <div className="size-full block md:hidden overflow-y-auto pt-16">
        <div className="flex flex-wrap justify-center gap-8 p-6 pb-24">
          {messages.map((msg) => (
            <CommunityWallCard
              key={msg.id}
              message={msg.message}
              patternIndex={msg.patternIndex ?? msg.pattern_index ?? 0}
              author={msg.creator_name || msg.author}
              profilePicture={msg.creator_avatar_url || msg.profilePicture}
              rotation={msg.rotation}
              className="h-75 w-63"
            />
          ))}
        </div>
      </div>

      {/* Desktop: Infinite canvas */}
      <div className="size-full hidden md:block">
        <InfiniteCanvas messages={messages} />
      </div>

      {/* Exact CommentForm Modal */}
      <LeaveNoteDialog
        open={open}
        onOpenChange={setOpen}
        user={user}
        onSubmitNote={handleAddNote}
      />
    </div>
  )
}

'use client'

import React, { useState, useRef, useMemo, type MouseEvent, type ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { Card, CardContent } from '@/components/ui/card'
import { CommunityWallCard, type CommunityMessage } from './community-wall-card'
import { IconCurrentLocation } from '@tabler/icons-react'

interface Position {
  x: number
  y: number
}

interface BoundingBox {
  x: number
  y: number
  width: number
  height: number
}

interface InfiniteCanvasProps {
  messages: CommunityMessage[]
  children?: ReactNode
  className?: string
}

// Card dimensions for collision detection
const CARD_WIDTH = 260
const CARD_HEIGHT = 300
const CARD_PADDING = 40 // Minimum space between cards

// Pseudo-random number generator with seed
function seededRandom(seed: string): number {
  let hash = 0
  for (let i = 0; i < seed.length; i++) {
    hash = (hash << 5) - hash + seed.charCodeAt(i)
    hash |= 0 // Convert to 32-bit integer
  }
  const x = Math.sin(hash++) * 10000
  return x - Math.floor(x)
}

// Check if two bounding boxes overlap
function checkCollision(box1: BoundingBox, box2: BoundingBox): boolean {
  return !(
    box1.x + box1.width < box2.x ||
    box1.x > box2.x + box2.width ||
    box1.y + box1.height < box2.y ||
    box1.y > box2.y + box2.height
  )
}

// Generate consistent random position for a message using radial distribution
// Cards are placed in a true 360-degree bloom from center with collision detection
function generatePosition(
  messageId: string,
  totalMessages: number,
  currentIndex: number,
  existingPositions: Position[],
): Position {
  const maxAttempts = 100

  const baseRadius = 250
  const cardsPerLayer = 8
  const layerSpacing = 380
  const layerRadius = Math.floor(currentIndex / cardsPerLayer) * layerSpacing

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const angleSeed = messageId + '_angle_' + attempt
    const radiusSeed = messageId + '_radius_' + attempt

    const angle = seededRandom(angleSeed) * Math.PI * 2
    const radiusVariation = seededRandom(radiusSeed) * 200
    const radius = baseRadius + radiusVariation + layerRadius

    const x = Math.cos(angle) * radius
    const y = Math.sin(angle) * radius

    const newBox: BoundingBox = {
      x: x - CARD_WIDTH / 2,
      y: y - CARD_HEIGHT / 2,
      width: CARD_WIDTH + CARD_PADDING,
      height: CARD_HEIGHT + CARD_PADDING,
    }

    let hasCollision = false
    for (const existingPos of existingPositions) {
      const existingBox: BoundingBox = {
        x: existingPos.x - CARD_WIDTH / 2,
        y: existingPos.y - CARD_HEIGHT / 2,
        width: CARD_WIDTH + CARD_PADDING,
        height: CARD_HEIGHT + CARD_PADDING,
      }

      if (checkCollision(newBox, existingBox)) {
        hasCollision = true
        break
      }
    }

    if (!hasCollision) {
      return { x: Math.round(x), y: Math.round(y) }
    }
  }

  const fallbackAngle = seededRandom(messageId + '_fallback') * Math.PI * 2
  const fallbackRadius = baseRadius + layerRadius + layerSpacing
  const x = Math.cos(fallbackAngle) * fallbackRadius
  const y = Math.sin(fallbackAngle) * fallbackRadius

  return { x: Math.round(x), y: Math.round(y) }
}

export function InfiniteCanvas({ messages, children, className }: InfiniteCanvasProps) {
  const [offset, setOffset] = useState<Position>({ x: 0, y: 0 })
  const [isDragging, setIsDragging] = useState(false)
  const [dragStart, setDragStart] = useState<Position>({ x: 0, y: 0 })
  const [isTransitioning, setIsTransitioning] = useState(false)
  const containerRef = useRef<HTMLDivElement>(null)

  // Memoized message positions with collision detection
  // The last card in array (first chronologically) is centered
  const messagePositions = useMemo(() => {
    const positions: Position[] = []
    return messages.map((message, index) => {
      let position: Position

      if (index === messages.length - 1) {
        position = { x: 0, y: 0 }
      } else {
        position = generatePosition(message.id, messages.length, index, positions)
      }

      positions.push(position)
      return {
        ...message,
        position,
      }
    })
  }, [messages])

  const handleMouseDown = (e: MouseEvent<HTMLDivElement>) => {
    e.preventDefault()
    setIsDragging(true)
    setDragStart({ x: e.clientX - offset.x, y: e.clientY - offset.y })
  }

  const handleMouseMove = (e: MouseEvent<HTMLDivElement>) => {
    if (!isDragging) return
    setOffset({
      x: e.clientX - dragStart.x,
      y: e.clientY - dragStart.y,
    })
  }

  const handleMouseUp = () => {
    if (isDragging) setIsDragging(false)
  }

  const handleMouseLeave = () => {
    if (isDragging) setIsDragging(false)
  }

  const handleRecenter = () => {
    setIsTransitioning(true)
    setOffset({ x: 0, y: 0 })
    setTimeout(() => {
      setIsTransitioning(false)
    }, 500)
  }

  const hasMoved = offset.x !== 0 || offset.y !== 0

  return (
    <div className={cn('relative w-full h-full min-h-125', className)}>
      <Card className="size-full bg-muted rounded-3xl border border-border flex-1 transition-all duration-300 overflow-hidden">
        <CardContent className="size-full p-0">
          <div
            ref={containerRef}
            className="absolute inset-0 overflow-hidden bg-card"
            style={{
              cursor: isDragging ? 'grabbing' : 'grab',
            }}
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseLeave}
          >
            {/* Background grid pattern */}
            <div className="absolute inset-0 bg-[radial-gradient(currentColor_0.0625rem,transparent_0.125rem)] opacity-10 bg-size-[1rem_1rem]" />

            {/* Canvas container that gets transformed */}
            <div
              className="absolute inset-0"
              style={{
                transform: `translate3d(${offset.x}px, ${offset.y}px, 0)`,
                willChange: isDragging ? 'transform' : 'auto',
                transition: isTransitioning ? 'transform 0.5s ease-in-out' : 'none',
              }}
            >
              {messagePositions.map((message) => (
                <div
                  key={message.id}
                  className="absolute"
                  style={{
                    left: '50%',
                    top: '50%',
                    transform: `translate(calc(-50% + ${message.position.x}px), calc(-50% + ${message.position.y}px))`,
                    pointerEvents: 'auto',
                  }}
                >
                  <CommunityWallCard
                    message={message.message}
                    patternIndex={message.patternIndex ?? message.pattern_index ?? 0}
                    author={message.creator_name || message.author}
                    profilePicture={message.creator_avatar_url || message.profilePicture}
                    rotation={message.rotation}
                    className="h-75 w-63"
                  />
                </div>
              ))}
            </div>

            {/* Recenter button - floating in top right, fades in when canvas moves */}
            <button
              type="button"
              onClick={handleRecenter}
              className={cn(
                'absolute right-4 top-4 z-10 flex size-10 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-md transition-opacity cursor-pointer',
                hasMoved ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none',
              )}
              aria-label="Recenter canvas"
              title="Recenter canvas"
            >
              <IconCurrentLocation className="size-5" />
            </button>
          </div>

          {children && children}
        </CardContent>
      </Card>
    </div>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import {
  Dialog,
  DialogBackdrop,
  DialogPortal,
  DialogViewport,
  DialogPopup,
  DialogHeader,
  DialogTitle,
  DialogClose,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { Input } from '@/components/ui/input'
import { Slider } from '@/components/ui/slider'
import { RadioGroup, Radio } from '@/components/ui/radio-group'
import { CommunityWallCard } from './community-wall-card'
import { patterns } from './patterns'
import { IconChevronLeft, IconChevronRight } from '@tabler/icons-react'
import { loading, confirm, deny } from '@usespaceui/sounds'

interface LeaveNoteDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  user?: any
  onSubmitNote: (note: {
    creator_name: string
    message: string
    pattern_index: number
    rotation: number
    creator_avatar_url?: string | null
  }) => Promise<boolean | void>
}

const config = {
  maxCommentLength: 110,
  rotation: {
    startAt: -10,
    default: 0,
    endAt: 10,
    step: 1,
  },
}

export function LeaveNoteDialog({
  open,
  onOpenChange,
  user,
  onSubmitNote,
}: LeaveNoteDialogProps) {
  const [screen, setScreen] = useState<'input' | 'preview'>('input')
  const [patternIndex, setPatternIndex] = useState(() =>
    Math.floor(Math.random() * patterns.length),
  )
  const [rotation, setRotation] = useState(config.rotation.default)
  const [comment, setComment] = useState('')
  const [authorName, setAuthorName] = useState(
    user?.user_metadata?.name || user?.name || '',
  )
  const [isSubmitting, setIsSubmitting] = useState(false)

  useEffect(() => {
    if (open) {
      if (user?.user_metadata?.name || user?.name) {
        setAuthorName(user.user_metadata?.name || user.name)
      }
    }
  }, [open, user])

  const handlePrevPattern = () => {
    setPatternIndex((prev) => (prev - 1 + patterns.length) % patterns.length)
  }

  const handleNextPattern = () => {
    setPatternIndex((prev) => (prev + 1) % patterns.length)
  }

  const onSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()

    if (!comment.trim()) {
      try {
        deny()
      } catch {}
      return
    }

    if (comment.length > config.maxCommentLength) {
      try {
        deny()
      } catch {}
      return
    }

    try {
      loading()
    } catch {}
    setIsSubmitting(true)

    try {
      const res = await onSubmitNote({
        creator_name: authorName.trim() || 'Anonymous',
        message: comment.trim(),
        pattern_index: patternIndex,
        rotation: rotation,
        creator_avatar_url: user?.user_metadata?.avatar_url || user?.avatarUrl,
      })

      if (res !== false) {
        try {
          confirm()
        } catch {}
        setComment('')
        setScreen('input')
        setPatternIndex(Math.floor(Math.random() * patterns.length))
        setRotation(config.rotation.default)
        onOpenChange(false)
      }
    } catch (err) {
      try {
        deny()
      } catch {}
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleNext = () => {
    if (comment.trim()) {
      setScreen('preview')
    }
  }

  const handleBack = () => {
    setScreen('input')
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogPortal>
        <DialogBackdrop />
        <DialogViewport className="p-4 sm:p-6">
          <DialogPopup className="w-full max-w-3xl overflow-hidden rounded-3xl border border-border bg-popover text-popover-foreground p-6">
            <DialogHeader className="p-0 pb-4 border-b border-border/40">
              <DialogTitle className="text-2xl font-bold text-start">Leave a Note</DialogTitle>
            </DialogHeader>

            <div className="pt-6 space-y-6">
              {/* Desktop: 2-column layout */}
              <div className="hidden md:grid md:grid-cols-2 gap-6">
                {/* Left column: Controls */}
                <div className="size-full space-y-4">
                  <form onSubmit={onSubmit} className="flex flex-col size-full space-y-4">
                    {!user?.user_metadata?.name && !user?.name && (
                      <div className="space-y-1.5">
                        <label className="text-sm font-medium text-foreground">Your Name</label>
                        <Input
                          placeholder="Your name or handle"
                          value={authorName}
                          onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                            setAuthorName(e.target.value)
                          }
                          maxLength={40}
                        />
                      </div>
                    )}

                    <div className="space-y-1.5">
                      <div className="flex items-center justify-between">
                        <label className="text-sm font-medium text-foreground">Your Note</label>
                        <span className="text-xs text-muted-foreground font-mono">
                          {comment.length} / {config.maxCommentLength}
                        </span>
                      </div>
                      <Textarea
                        name="comment"
                        placeholder="Write your note here..."
                        rows={4}
                        value={comment}
                        onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) =>
                          setComment(e.target.value)
                        }
                        required
                        maxLength={config.maxCommentLength}
                        className="resize-none"
                      />
                    </div>

                    <div className="space-y-3 pt-1">
                      <div className="flex items-center gap-2">
                        <label className="text-sm font-medium min-w-16">Rotation</label>
                        <Slider
                          value={rotation}
                          min={config.rotation.startAt}
                          max={config.rotation.endAt}
                          step={config.rotation.step}
                          onValueChange={(value: any) => {
                            const newValue = Array.isArray(value) ? value[0] : value
                            setRotation(newValue as number)
                          }}
                          className="flex-1"
                        />
                        <span className="text-sm w-12 text-right font-mono">{rotation}°</span>
                      </div>

                      <div className="flex items-center gap-2">
                        <label className="text-sm font-medium min-w-16">Pattern</label>
                        <RadioGroup
                          value={patternIndex.toString()}
                          onValueChange={(value: any) => setPatternIndex(parseInt(value))}
                          className="flex gap-2 flex-1 flex-row"
                        >
                          {patterns.map((_, index) => (
                            <Radio
                              key={index}
                              value={index.toString()}
                              aria-label={`Pattern ${index + 1}`}
                            />
                          ))}
                        </RadioGroup>
                      </div>
                    </div>

                    <div className="flex gap-2 pt-4 mt-auto">
                      <Button
                        type="button"
                        variant="outline"
                        className="flex-1"
                        onClick={() => {
                          setComment('')
                          onOpenChange(false)
                        }}
                      >
                        Cancel
                      </Button>
                      <Button
                        type="submit"
                        variant="default"
                        className="flex-1"
                        disabled={!comment.trim() || isSubmitting}
                      >
                        {isSubmitting ? 'Submitting...' : 'Submit'}
                      </Button>
                    </div>
                  </form>
                </div>

                {/* Right column: Preview */}
                <div className="flex flex-col items-center justify-center gap-4">
                  <div className="flex items-center gap-4 md:gap-6">
                    <Button
                      type="button"
                      variant="outline"
                      size="icon"
                      onClick={handlePrevPattern}
                      aria-label="Previous pattern"
                    >
                      <IconChevronLeft className="size-5" />
                    </Button>

                    <div className="relative">
                      <CommunityWallCard
                        patternIndex={patternIndex}
                        author={authorName || 'You'}
                        profilePicture={user?.user_metadata?.avatar_url || user?.avatarUrl}
                        rotation={rotation}
                        message={comment || 'Your note preview will appear here...'}
                        className="h-[380px] w-[280px]"
                      />
                    </div>

                    <Button
                      type="button"
                      variant="outline"
                      size="icon"
                      onClick={handleNextPattern}
                      aria-label="Next pattern"
                    >
                      <IconChevronRight className="size-5" />
                    </Button>
                  </div>
                </div>
              </div>

              {/* Mobile: Step-by-step */}
              <div className="md:hidden">
                {screen === 'input' ? (
                  <form
                    onSubmit={(e) => {
                      e.preventDefault()
                      handleNext()
                    }}
                    className="space-y-4"
                  >
                    {!user?.user_metadata?.name && !user?.name && (
                      <div className="space-y-1.5">
                        <label className="text-sm font-medium text-foreground">Your Name</label>
                        <Input
                          placeholder="Your name or handle"
                          value={authorName}
                          onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                            setAuthorName(e.target.value)
                          }
                          maxLength={40}
                        />
                      </div>
                    )}

                    <div className="space-y-1.5">
                      <div className="flex items-center justify-between">
                        <label className="text-sm font-medium text-foreground">Your Note</label>
                        <span className="text-xs text-muted-foreground font-mono">
                          {comment.length} / {config.maxCommentLength}
                        </span>
                      </div>
                      <Textarea
                        name="comment"
                        placeholder="Write your note here..."
                        rows={4}
                        value={comment}
                        onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) =>
                          setComment(e.target.value)
                        }
                        required
                        maxLength={config.maxCommentLength}
                        className="resize-none"
                      />
                    </div>

                    <div className="flex gap-2 pt-2">
                      <Button
                        type="button"
                        variant="outline"
                        className="flex-1"
                        onClick={() => {
                          setComment('')
                          onOpenChange(false)
                        }}
                      >
                        Cancel
                      </Button>
                      <Button
                        type="button"
                        variant="default"
                        className="flex-1"
                        onClick={handleNext}
                        disabled={!comment.trim()}
                      >
                        Continue
                      </Button>
                    </div>
                  </form>
                ) : (
                  <div className="flex flex-col items-center gap-4">
                    <div className="relative">
                      <CommunityWallCard
                        patternIndex={patternIndex}
                        author={authorName || 'You'}
                        profilePicture={user?.user_metadata?.avatar_url || user?.avatarUrl}
                        rotation={rotation}
                        message={comment}
                        className="h-[340px] w-[260px]"
                      />
                    </div>

                    <div className="flex gap-2">
                      <Button
                        type="button"
                        variant="outline"
                        size="icon"
                        onClick={handlePrevPattern}
                        aria-label="Previous pattern"
                      >
                        <IconChevronLeft className="size-5" />
                      </Button>
                      <Button
                        type="button"
                        variant="outline"
                        size="icon"
                        onClick={handleNextPattern}
                        aria-label="Next pattern"
                      >
                        <IconChevronRight className="size-5" />
                      </Button>
                    </div>

                    <div className="flex flex-col gap-3 w-full max-w-sm">
                      <div className="flex items-center gap-2">
                        <label className="text-sm font-medium min-w-16">Rotation</label>
                        <Slider
                          value={rotation}
                          min={config.rotation.startAt}
                          max={config.rotation.endAt}
                          step={config.rotation.step}
                          onValueChange={(value: any) => {
                            const newValue = Array.isArray(value) ? value[0] : value
                            setRotation(newValue as number)
                          }}
                          className="flex-1"
                        />
                        <span className="text-sm w-12 text-right font-mono">{rotation}°</span>
                      </div>

                      <div className="flex items-center gap-2">
                        <label className="text-sm font-medium min-w-16">Pattern</label>
                        <RadioGroup
                          value={patternIndex.toString()}
                          onValueChange={(value: any) => setPatternIndex(parseInt(value))}
                          className="flex gap-2 flex-1 flex-row"
                        >
                          {patterns.map((_, index) => (
                            <Radio
                              key={index}
                              value={index.toString()}
                              aria-label={`Pattern ${index + 1}`}
                            />
                          ))}
                        </RadioGroup>
                      </div>
                    </div>

                    <form onSubmit={onSubmit} className="flex gap-2 w-full max-w-sm pt-2">
                      <Button
                        type="button"
                        variant="outline"
                        className="flex-1"
                        onClick={handleBack}
                      >
                        Back
                      </Button>
                      <Button
                        type="submit"
                        variant="default"
                        className="flex-1"
                        disabled={!comment.trim() || isSubmitting}
                      >
                        {isSubmitting ? 'Submitting...' : 'Submit'}
                      </Button>
                    </form>
                  </div>
                )}
              </div>
            </div>
          </DialogPopup>
        </DialogViewport>
      </DialogPortal>
    </Dialog>
  )
}
